class AbstractNode():

    def __init__(self, is_root, time_independent, node_type, partial_cache, height, params, immutable_attributes):

        self.is_root = is_root
        self.time_independent = time_independent
        self.node_type = node_type
        self.partial_cache = partial_cache
        self.height = height
        self.params = params

        self._evaluation_cache = None
        self._evaluation_cache_time = None
        self.immutable_attributes = immutable_attributes

    def __getstate__(self):
        state = self.__dict__.copy()
        state["_evaluation_cache"] = None
        state["_evaluation_cache_time"] = None
        return state

    def __getattribute__(self, name):
        if name == "id" or name == "locked" or name[:2] == "__":
            return super().__getattribute__(name)
        elif "id" in self.__dict__ and tree.has_node(self.__dict__["id"]) and self != tree.node(self.__dict__["id"]):
            return tree.node(self.__dict__["id"]).__getattribute__(name)
        else:
            return super().__getattribute__(name)

    def __setattr__(self, name, value):
        if name == "locked" and "locked" not in self.__dict__:
            self.__dict__["locked"] = value
        elif "locked" in self.__dict__ and name in self.immutable_attributes:
            raise TypeError(f"Cannot set immutable attribute {name} for Node")
        elif "id" in self.__dict__ and tree.has_node(self.__dict__["id"]) and self != tree.node(self.__dict__["id"]):
            tree.node(self.__dict__["id"]).__setattr__(name, value)
        else:
            return super().__setattr__(name, value)

    @property
    def child_node_ids(self):
        return tree.get_child_ids(self.id)

    @property
    def children(self):
        return tree.get_children(self.id)

    @classmethod
    def mandatory_parameters(cls):
        return []

    @classmethod
    def expose_mcp(cls):
        return True

    @classmethod
    def chat_description(cls):
        return f"used {cls.__name__}"

    @classmethod
    def description(cls):
        raise NotImplementedError(f"{cls.__name__} has not yet implemented the description method")

    @classmethod
    def brief_description(cls):
        return cls.description()

    @classmethod
    def param_descriptions(cls):
        raise NotImplementedError(f"{cls.__name__} has not yet implemented the param_descriptions method")

    @classmethod
    def _parse_init_docstring(cls):
        init_fn = getattr(cls, "__init__", None)
        doc = inspect.getdoc(init_fn) if init_fn is not None else None
        if not doc:
            return {"description": "", "param_descriptions": {}}

        lines = doc.splitlines()
        description_lines = []
        in_args = False

        for line in lines:
            stripped = line.strip()
            if stripped == "Args:":
                in_args = True
                break
            description_lines.append(line)

        description = "\n".join(description_lines).strip()

        if not in_args:
            return {"description": description, "param_descriptions": {}}

        param_descriptions = {}
        current_param = None

        for line in lines[len(description_lines) + 1:]:
            if not line.strip():
                continue

            match = re.match(r"^\s*([a-zA-Z_]\w*)\s*:\s*(.*)$", line)
            if match:
                current_param = match.group(1)
                param_descriptions[current_param] = match.group(2).strip()
